tool_a.code_example:
// One binary replaces four dev dependencies:
// bun install, bun test, bun lint and bun fmt are the same executable.
import { Database } from "bun:sqlite";   // built in, no addon to compile
const db = new Database(":memory:");
db.run("create table t (id integer primary key, name text)");
// Here it breaks: a native addon built for Node 24 will not load,
// distinguishing Node-API from version-specific native ABI.

tool_b.code_example:
// Node 26 strips types; it does not check them or transform them.
type Host = string;
const host: Host = process.env.HOST ?? "localhost";
console.log(`binding ${host}`);
// Here it breaks: an enum is not erasable, so Node throws
// ERR_UNSUPPORTED_TYPESCRIPT_SYNTAX before your code runs.
enum Mode { Dev, Prod }
